Here's a complete, runnable Java implementation of Red-Black Tree with insertion and deletion operations, following standard CLRS algorithm conventions. It includes test code so you can run it directly and submit it for your assignment:

```java
public class RedBlackTree {
    // Red = true, Black = false
    private static final boolean RED = true;
    private static final boolean BLACK = false;

    // Node class for Red-Black Tree
    public static class Node {
        int key;
        boolean color;
        Node left, right, parent;

        public Node(int key) {
            this.key = key;
            this.color = RED; // New nodes are always red by default
            this.left = this.right = this.parent = NIL;
        }
    }

    // Sentinel NIL node (replaces null to simplify boundary checks)
    public static final Node NIL = new Node(0);
    static {
        NIL.color = BLACK;
    }

    // Root of the tree
    private Node root = NIL;

    // Left rotation
    private void leftRotate(Node x) {
        Node y = x.right;
        x.right = y.left;
        if (y.left != NIL) {
            y.left.parent = x;
        }
        y.parent = x.parent;
        if (x.parent == NIL) {
            this.root = y;
        } else if (x == x.parent.left) {
            x.parent.left = y;
        } else {
            x.parent.right = y;
        }
        y.left = x;
        x.parent = y;
    }

    // Right rotation
    private void rightRotate(Node y) {
        Node x = y.left;
        y.left = x.right;
        if (x.right != NIL) {
            x.right.parent = y;
        }
        x.parent = y.parent;
        if (y.parent == NIL) {
            this.root = x;
        } else if (y == y.parent.right) {
            y.parent.right = x;
        } else {
            y.parent.left = x;
        }
        x.right = y;
        y.parent = x;
    }

    // Insert a new key into the tree
    public void insert(int key) {
        Node z = new Node(key);
        Node y = NIL;
        Node x = root;

        // Standard BST insert
        while (x != NIL) {
            y = x;
            if (z.key < x.key) {
                x = x.left;
            } else {
                x = x.right;
            }
        }

        z.parent = y;
        if (y == NIL) {
            root = z;
        } else if (z.key < y.key) {
            y.left = z;
        } else {
            y.right = z;
        }

        // Fix Red-Black properties if violated
        insertFixup(z);
    }

    // Fix Red-Black properties after insertion
    private void insertFixup(Node z) {
        while (z.parent.color == RED) {
            if (z.parent == z.parent.parent.left) {
                Node uncle = z.parent.parent.right;
                // Case 1: Uncle is red, only recolor
                if (uncle.color == RED) {
                    z.parent.color = BLACK;
                    uncle.color = BLACK;
                    z.parent.parent.color = RED;
                    z = z.parent.parent;
                } else {
                    // Case 2: Uncle is black, z is right child
                    if (z == z.parent.right) {
                        z = z.parent;
                        leftRotate(z);
                    }
                    // Case 3: Uncle is black, z is left child
                    z.parent.color = BLACK;
                    z.parent.parent.color = RED;
                    rightRotate(z.parent.parent);
                }
            } else { // Mirror case: parent is right child of grandparent
                Node uncle = z.parent.parent.left;
                if (uncle.color == RED) {
                    z.parent.color = BLACK;
                    uncle.color = BLACK;
                    z.parent.parent.color = RED;
                    z = z.parent.parent;
                } else {
                    if (z == z.parent.left) {
                        z = z.parent;
                        rightRotate(z);
                    }
                    z.parent.color = BLACK;
                    z.parent.parent.color = RED;
                    leftRotate(z.parent.parent);
                }
            }
            if (z == root) break;
        }
        root.color = BLACK; // Root is always black
    }

    // Transplant: replace subtree rooted at u with subtree rooted at v
    private void transplant(Node u, Node v) {
        if (u.parent == NIL) {
            root = v;
        } else if (u == u.parent.left) {
            u.parent.left = v;
        } else {
            u.parent.right = v;
        }
        v.parent = u.parent;
    }

    // Find minimum node in a subtree
    private Node minimum(Node x) {
        while (x.left != NIL) {
            x = x.left;
        }
        return x;
    }

    // Delete node with given key
    public void delete(int key) {
        Node z = NIL;
        Node temp = root;
        // Find the node to delete
        while (temp != NIL) {
            if (temp.key == key) {
                z = temp;
                break;
            }
            if (temp.key < key) {
                temp = temp.right;
            } else {
                temp = temp.left;
            }
        }
        if (z == NIL) {
            System.out.println("Key " + key + " not found in tree");
            return;
        }

        Node y = z;
        boolean yOriginalColor = y.color;
        Node x;
        if (z.left == NIL) {
            x = z.right;
            transplant(z, z.right);
        } else if (z.right == NIL) {
            x = z.left;
            transplant(z, z.left);
        } else {
            y = minimum(z.right);
            yOriginalColor = y.color;
            x = y.right;
            if (y.parent == z) {
                x.parent = y;
            } else {
                transplant(y, y.right);
                y.right = z.right;
                y.right.parent = y;
            }
            transplant(z, y);
            y.left = z.left;
            y.left.parent = y;
            y.color = z.color;
        }
        // Fix Red-Black properties only if deleted node was black
        if (yOriginalColor == BLACK) {
            deleteFixup(x);
        }
    }

    // Fix Red-Black properties after deletion
    private void deleteFixup(Node x) {
        while (x != root && x.color == BLACK) {
            if (x == x.parent.left) {
                Node sibling = x.parent.right;
                // Case 1: Sibling is red
                if (sibling.color == RED) {
                    sibling.color = BLACK;
                    x.parent.color = RED;
                    leftRotate(x.parent);
                    sibling = x.parent.right;
                }
                // Case 2: Sibling is black, both children are black
                if (sibling.left.color == BLACK && sibling.right.color == BLACK) {
                    sibling.color = RED;
                    x = x.parent;
                } else {
                    // Case 3: Sibling black, left child red, right child black
                    if (sibling.right.color == BLACK) {
                        sibling.left.color = BLACK;
                        sibling.color = RED;
                        rightRotate(sibling);
                        sibling = x.parent.right;
                    }
                    // Case 4: Sibling black, right child red
                    sibling.color = x.parent.color;
                    x.parent.color = BLACK;
                    sibling.right.color = BLACK;
                    leftRotate(x.parent);
                    x = root;
                }
            } else { // Mirror case: x is right child
                Node sibling = x.parent.left;
                if (sibling.color == RED) {
                    sibling.color = BLACK;
                    x.parent.color = RED;
                    rightRotate(x.parent);
                    sibling = x.parent.left;
                }
                if (sibling.right.color == BLACK && sibling.left.color == BLACK) {
                    sibling.color = RED;
                    x = x.parent;
                } else {
                    if (sibling.left.color == BLACK) {
                        sibling.right.color = BLACK;
                        sibling.color = RED;
                        leftRotate(sibling);
                        sibling = x.parent.left;
                    }
                    sibling.color = x.parent.color;
                    x.parent.color = BLACK;
                    sibling.left.color = BLACK;
                    rightRotate(x.parent);
                    x = root;
                }
            }
        }
        x.color = BLACK;
    }

    // Inorder traversal to print sorted keys
    public void inorderTraversal() {
        inorderHelper(root);
        System.out.println();
    }

    private void inorderHelper(Node node) {
        if (node != NIL) {
            inorderHelper(node.left);
            System.out.print(node.key + " ");
            inorderHelper(node.right);
        }
    }

    // Test main method
    public static void main(String[] args) {
        RedBlackTree tree = new RedBlackTree();

        // Insert test keys
        int[] keys = {10, 20, 30, 15, 25, 5, 3};
        for (int key : keys) {
            tree.insert(key);
        }

        System.out.println("Inorder traversal after insertion (sorted):");
        tree.inorderTraversal();

        // Test deletion
        tree.delete(20);
        System.out.println("\nInorder traversal after deleting 20:");
        tree.inorderTraversal();

        tree.delete(10);
        System.out.println("\nInorder traversal after deleting 10:");
        tree.inorderTraversal();
    }
}
```

