### `MainActivity.java`
```java
package com.example.todolist;

import android.Manifest;
import android.content.Intent;
import android.os.Bundle;
import android.view.LayoutInflater;
import android.view.View;
import android.widget.Toast;

import androidx.activity.result.ActivityResultLauncher;
import androidx.activity.result.contract.ActivityResultContracts;
import androidx.appcompat.app.AlertDialog;
import androidx.appcompat.app.AppCompatActivity;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import com.google.android.material.floatingactionbutton.FloatingActionButton;

import java.util.concurrent.Executors;

public class MainActivity extends AppCompatActivity {
    private TaskAdapter taskAdapter;
    private AppDatabase db;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        requestNotificationPermission();

        RecyclerView recyclerView = findViewById(R.id.tasks_recycler_view);
        FloatingActionButton fabAdd = findViewById(R.id.fab_add_task);

        recyclerView.setLayoutManager(new LinearLayoutManager(this));
        taskAdapter = new TaskAdapter();
        recyclerView.setAdapter(taskAdapter);

        db = AppDatabase.getInstance(this);
        db.taskDao().getAllTasks().observe(this, tasks -> {
            taskAdapter.setTaskList(tasks);
        });

        taskAdapter.setOnTaskClickListener(new TaskAdapter.OnTaskClickListener() {
            @Override
            public void onEditClick(Task task) {
                Intent intent = new Intent(MainActivity.this, AddEditTaskActivity.class);
                intent.putExtra("EXTRA_TASK_ID", task.getId());
                intent.putExtra("EXTRA_TASK_TITLE", task.getTitle());
                intent.putExtra("EXTRA_TASK_DESC", task.getDescription());
                intent.putExtra("EXTRA_TASK_REMINDER", task.getReminderTime());
                startActivity(intent);
            }

            @Override
            public void onDeleteClick(Task task) {
                new AlertDialog.Builder(MainActivity.this)
                        .setTitle("Delete Task")
                        .setMessage("Are you sure you want to delete this task?")
                        .setPositiveButton("Delete", (dialog, which) -> {
                            Executors.newSingleThreadExecutor().execute(() -> {
                                db.taskDao().delete(task);
                                // Cancel alarm
                                AlarmReceiver.cancelReminder(MainActivity.this, task.getId());
                                runOnUiThread(() -> Toast.makeText(MainActivity.this, "Task deleted", Toast.LENGTH_SHORT).show());
                            });
                        })
                        .setNegativeButton("Cancel", null)
                        .show();
            }
        });

        fabAdd.setOnClickListener(v -> startActivity(new Intent(MainActivity.this, AddEditTaskActivity.class)));
    }

    private final ActivityResultLauncher<String> requestPermissionLauncher =
            registerForActivityResult(new ActivityResultContracts.RequestPermission(), isGranted -> {
                if (!isGranted) {
                    Toast.makeText(this, "Notification permission is required for reminders", Toast.LENGTH_SHORT).show();
                }
            });

    private void requestNotificationPermission() {
        if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.TIRAMISU) {
            requestPermissionLauncher.launch(Manifest.permission.POST_NOTIFICATIONS);
        }
    }
}
