```java
package com.example.todolist;

import android.app.DatePickerDialog;
import android.app.TimePickerDialog;
import android.content.Intent;
import android.os.Bundle;
import android.widget.Button;
import android.widget.EditText;
import android.widget.TextView;
import android.widget.Toast;

import androidx.appcompat.app.AppCompatActivity;

import java.text.SimpleDateFormat;
import java.util.Calendar;
import java.util.Date;
import java.util.Locale;
import java.util.concurrent.Executors;

public class AddEditTaskActivity extends AppCompatActivity {
    private EditText etTitle, etDescription;
    private TextView tvSelectedReminder;
    private Button btnSave, btnSetReminder;
    private long reminderTime = 0;
    private int taskId = -1;
    private boolean isEdit = false;
    private AppDatabase db;
    private SimpleDateFormat sdf = new SimpleDateFormat("dd MMM yyyy, HH:mm", Locale.getDefault());

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_add_edit_task);

        etTitle = findViewById(R.id.et_task_title);
        etDescription = findViewById(R.id.et_task_description);
        tvSelectedReminder = findViewById(R.id.tv_selected_reminder);
        btnSave = findViewById(R.id.btn_save_task);
        btnSetReminder = findViewById(R.id.btn_set_reminder);
        db = AppDatabase.getInstance(this);

        if (getIntent().hasExtra("EXTRA_TASK_ID")) {
            isEdit = true;
            taskId = getIntent().getIntExtra("EXTRA_TASK_ID", -1);
            etTitle.setText(getIntent().getStringExtra("EXTRA_TASK_TITLE"));
            etDescription.setText(getIntent().getStringExtra("EXTRA_TASK_DESC"));
            reminderTime = getIntent().getLongExtra("EXTRA_TASK_REMINDER", 0);
            if (reminderTime > 0) {
                tvSelectedReminder.setText("Selected Reminder: " + sdf.format(new Date(reminderTime)));
            }
            setTitle("Edit Task");
        } else {
            setTitle("Add New Task");
        }

        btnSetReminder.setOnClickListener(v -> openDateTimePicker());

        btnSave.setOnClickListener(v -> saveTask());
    }

    private void openDateTimePicker() {
        Calendar calendar = Calendar.getInstance();
        if (reminderTime > 0) calendar.setTimeInMillis(reminderTime);

        DatePickerDialog datePicker = new DatePickerDialog(this, (view, year, month, dayOfMonth) -> {
            calendar.set(year, month, dayOfMonth);
            new TimePickerDialog(this, (view1, hourOfDay, minute) -> {
                calendar.set(Calendar.HOUR_OF_DAY, hourOfDay);
                calendar.set(Calendar.MINUTE, minute);
                reminderTime = calendar.getTimeInMillis();
                tvSelectedReminder.setText("Selected Reminder: " + sdf.format(calendar.getTime()));
            }, calendar.get(Calendar.HOUR_OF_DAY), calendar.get(Calendar.MINUTE), true).show();
        }, calendar.get(Calendar.YEAR), calendar.get(Calendar.MONTH), calendar.get(Calendar.DAY_OF_MONTH));
        datePicker.show();
    }

    private void saveTask() {
        String title = etTitle.getText().toString().trim();
        String description = etDescription.getText().toString().trim();

        if (title.isEmpty()) {
            etTitle.setError("Title is required");
            return;
        }

        Executors.newSingleThreadExecutor().execute(() -> {
            if (isEdit) {
                Task task = new Task(title, description, reminderTime, false);
                task.setId(taskId);
                db.taskDao().update(task);
                if (reminderTime > 0) {
                    AlarmReceiver.scheduleReminder(this, task.getId(), reminderTime);
                }
                runOnUiThread(() -> {
                    Toast.makeText(this, "Task updated", Toast.LENGTH_SHORT).show();
                    finish();
                });
            } else {
                Task task = new Task(title, description, reminderTime, false);
                long id = db.taskDao().insert(task);
                if (reminderTime > 0) {
                    AlarmReceiver.scheduleReminder(this, (int)id, reminderTime);
                }
                runOnUiThread(() -> {
                    Toast.makeText(this, "Task added", Toast.LENGTH_SHORT).show();
                    finish();
                });
            }
        });
    }
}
